"""Private, evidence-linked research scenario artifacts."""

from __future__ import annotations

import hashlib
import json
import math
import os
import re
import stat
import time
import uuid
from datetime import date, datetime, time as day_time, timedelta, timezone
from pathlib import Path
from typing import Any, Mapping, Sequence

from src.config.paths import get_runs_dir, get_runtime_root

_ARTIFACT_ID = re.compile(r"^[a-f0-9]{32}$")
_RUN_ID = re.compile(r"^[A-Za-z0-9_-]{1,128}$")
_SYMBOL = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._=^:-]{0,31}$")
_FIELD = re.compile(r"^(?:open|high|low|close|adj_close|price|volume|amount|turnover)$")
_OPERATORS = {"gt", "gte", "lt", "lte", "equal"}
_MARKET_TOOLS = {"get_market_data", "get_br_market_data"}
_SOURCELESS = {"", "auto", "unknown", "none", "null"}
_MAX_LEDGER_BYTES = 16 * 1024 * 1024
_MAX_ARTIFACT_BYTES = 1024 * 1024


class ScenarioError(ValueError):
    """A scenario input or private artifact failed validation."""


def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def _parse_time(value: Any, *, date_end: bool = False) -> datetime:
    if not isinstance(value, str) or not value.strip():
        raise ScenarioError("timestamp must be an ISO-8601 string")
    text = value.strip()
    try:
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", text):
            parsed_date = date.fromisoformat(text)
            return datetime.combine(
                parsed_date,
                day_time.max if date_end else day_time.min,
                tzinfo=timezone.utc,
            )
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError as exc:
        raise ScenarioError("timestamp must be an ISO-8601 date or datetime") from exc
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _timestamp(value: datetime | None) -> str | None:
    return value.isoformat().replace("+00:00", "Z") if value else None


def _is_reparse_point(path: Path) -> bool:
    try:
        info = path.lstat()
    except OSError:
        return False
    return stat.S_ISLNK(info.st_mode) or bool(getattr(info, "st_file_attributes", 0) & 0x400)


def _assert_no_links(path: Path, boundary: Path) -> None:
    boundary = boundary.resolve(strict=True)
    lexical = Path(os.path.abspath(str(path)))
    try:
        relative = lexical.relative_to(boundary)
    except ValueError as exc:
        raise ScenarioError("scenario path is outside the private root") from exc
    current = boundary
    if _is_reparse_point(current):
        raise ScenarioError("scenario root must not be a linked directory")
    for part in relative.parts:
        current = current / part
        if _is_reparse_point(current):
            raise ScenarioError("scenario paths must not contain links or junctions")


def _private_runtime_root() -> Path:
    raw_root = Path(get_runtime_root()).expanduser()
    if not raw_root.is_absolute() or _is_reparse_point(raw_root):
        raise ScenarioError("private runtime root is unavailable")
    try:
        return raw_root.resolve(strict=True)
    except OSError as exc:
        raise ScenarioError("private runtime root is unavailable") from exc


def _private_roots() -> tuple[Path, Path]:
    root = _private_runtime_root()
    raw_runs = Path(get_runs_dir()).expanduser()
    if not raw_runs.is_absolute() or _is_reparse_point(raw_runs):
        raise ScenarioError("private runtime root is unavailable")
    try:
        runs = raw_runs.resolve(strict=True)
    except OSError as exc:
        raise ScenarioError("private run root is unavailable") from exc
    if not runs.is_dir() or not runs.is_relative_to(root):
        raise ScenarioError("private run root is invalid")
    _assert_no_links(runs, root)
    return root, runs


def _private_run_dir(run_dir: str | Path) -> tuple[Path, Path, Path]:
    if not isinstance(run_dir, (str, Path)) or not str(run_dir).strip():
        raise ScenarioError("the injected run directory is required")
    raw = str(run_dir)
    if raw.startswith(("\\\\", "//")):
        raise ScenarioError("network paths are not allowed")
    candidate = Path(raw).expanduser()
    if not candidate.is_absolute():
        raise ScenarioError("the injected run directory must be absolute")
    root, runs = _private_roots()
    lexical = Path(os.path.abspath(str(candidate)))
    try:
        lexical.relative_to(runs)
    except ValueError as exc:
        raise ScenarioError("the injected run directory is outside the private runs root") from exc
    if lexical.parent != runs:
        raise ScenarioError("the run directory must be a direct child of the private runs root")
    try:
        _assert_no_links(lexical, runs)
        resolved = lexical.resolve(strict=True)
    except OSError as exc:
        raise ScenarioError("the injected run directory is unavailable") from exc
    if resolved.parent != runs or not resolved.is_dir() or not _RUN_ID.fullmatch(resolved.name):
        raise ScenarioError("the injected run directory is outside the private runs root")
    return root, runs, resolved


def _private_child(path: Path, boundary: Path, *, strict: bool) -> Path:
    _assert_no_links(path, boundary)
    try:
        resolved = path.resolve(strict=strict)
    except OSError as exc:
        raise ScenarioError("private scenario artifact is unavailable") from exc
    if not resolved.is_relative_to(boundary.resolve(strict=True)):
        raise ScenarioError("private scenario artifact escaped its root")
    return resolved


def _read_ledger(run_dir: Path) -> list[dict[str, Any]]:
    artifacts = run_dir / "artifacts"
    ledger_path = artifacts / "grounding_evidence.json"
    artifacts = _private_child(artifacts, run_dir, strict=True)
    ledger_path = _private_child(ledger_path, run_dir, strict=True)
    if ledger_path.parent != artifacts or ledger_path.stat().st_size > _MAX_LEDGER_BYTES:
        raise ScenarioError("grounding evidence ledger is invalid or too large")
    try:
        ledger = json.loads(ledger_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ScenarioError("grounding evidence ledger could not be read") from exc
    if (
        not isinstance(ledger, dict)
        or ledger.get("schema_version") != 1
        or not isinstance(ledger.get("evidence"), list)
    ):
        raise ScenarioError("grounding evidence ledger has an invalid shape")
    return [row for row in ledger["evidence"] if isinstance(row, dict)]


def _producer_receipt(root: Path) -> dict[str, Any]:
    receipt_path = Path(__file__).resolve().parents[1] / "mona-source.json"
    if _is_reparse_point(receipt_path) or not receipt_path.is_file():
        raise ScenarioError("native source receipt is unavailable")
    try:
        receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ScenarioError("native source receipt is invalid") from exc
    instance_id = os.environ.get("MONA_VIBE_INSTANCE_ID", "").strip()
    if (
        not isinstance(receipt, dict)
        or not isinstance(receipt.get("snapshot_id"), str)
        or not isinstance(receipt.get("patches"), list)
        or not instance_id
    ):
        raise ScenarioError("native source identity is unavailable")
    return {
        "snapshot_id": receipt["snapshot_id"],
        "patches": receipt["patches"],
        "instance_id": instance_id,
        "data_root_sha256": hashlib.sha256(str(root.resolve()).encode()).hexdigest(),
    }


def _canonical_json(value: Any) -> bytes:
    return json.dumps(
        value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
    ).encode("utf-8")


def _resolve_evidence(
    evidence: Sequence[Mapping[str, Any]],
    *,
    symbol: str,
    field: str,
    fact: Any,
    threshold: float | int,
    as_of: datetime,
) -> dict[str, Any]:
    if not isinstance(fact, dict) or set(fact) != {"symbol", "field", "timestamp", "value"}:
        raise ScenarioError("a numeric threshold requires an exact observed market fact")
    fact_symbol = fact.get("symbol")
    fact_field = fact.get("field")
    fact_timestamp = fact.get("timestamp")
    fact_value = fact.get("value")
    if (
        not isinstance(fact_symbol, str)
        or fact_symbol.strip().upper() != symbol
        or not isinstance(fact_field, str)
        or fact_field.strip().casefold() != field
        or not isinstance(fact_timestamp, str)
        or not _is_number(fact_value)
        or fact_value != threshold
    ):
        raise ScenarioError("threshold fact must exactly match its symbol, field, timestamp and value")
    fact_time = _parse_time(fact_timestamp)
    if fact_time > as_of:
        raise ScenarioError("threshold fact is later than the scenario as-of time")
    matches: list[dict[str, Any]] = []
    for row in evidence:
        source = row.get("source")
        tool = row.get("tool")
        timestamp = row.get("timestamp")
        if (
            row.get("status") != "observed"
            or tool not in _MARKET_TOOLS
            or not isinstance(source, str)
            or source.strip().casefold() in _SOURCELESS
            or str(row.get("symbol") or "").strip().upper() != symbol
            or str(row.get("field") or "").strip().casefold() != field
            or timestamp != fact_timestamp
            or not _is_number(row.get("value"))
            or row.get("value") != fact_value
        ):
            continue
        if _parse_time(timestamp) <= as_of:
            matches.append(dict(row))
    if not matches:
        raise ScenarioError("no matching source-backed observed fact exists in this run")
    row = sorted(matches, key=lambda item: (str(item.get("source")), str(item.get("call_id"))))[0]
    digest = hashlib.sha256(_canonical_json(row)).hexdigest()
    return {
        "evidence_ref": f"sha256:{digest}",
        "source": str(row["source"]).strip(),
        "observed_at": fact_timestamp,
    }


def _text(value: Any, name: str, *, maximum: int = 500) -> str:
    if not isinstance(value, str) or not value.strip() or len(value.strip()) > maximum:
        raise ScenarioError(f"{name} must be a non-empty string no longer than {maximum} characters")
    return value.strip()


def _conditions(
    values: Any,
    *,
    symbol: str,
    as_of: datetime,
    evidence: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    if not isinstance(values, list) or len(values) > 30:
        raise ScenarioError("conditions must be a list of at most 30 items")
    result: list[dict[str, Any]] = []
    for condition in values:
        expected = {"field", "operator", "threshold", "fact", "missing_data"}
        if not isinstance(condition, dict) or set(condition) - expected or not {"field", "operator"} <= set(condition):
            raise ScenarioError("condition contains unknown or missing fields")
        field = str(condition["field"]).strip().casefold()
        operator = condition["operator"]
        if not _FIELD.fullmatch(field) or operator not in _OPERATORS:
            raise ScenarioError("condition field or comparison operator is not supported")
        threshold = condition.get("threshold")
        fact = condition.get("fact")
        missing = condition.get("missing_data")
        if threshold is None:
            if fact is not None or not isinstance(missing, str) or not missing.strip():
                raise ScenarioError("a missing threshold must have no fact and explain missing_data")
            result.append({
                "field": field, "operator": operator, "threshold": None,
                "evidence_ref": None, "source": None, "observed_at": None,
                "missing_data": _text(missing, "missing_data", maximum=300),
            })
            continue
        if not _is_number(threshold) or missing not in (None, ""):
            raise ScenarioError("numeric thresholds require evidence and cannot include missing_data")
        provenance = _resolve_evidence(
            evidence, symbol=symbol, field=field, fact=fact,
            threshold=threshold, as_of=as_of,
        )
        result.append({
            "field": field, "operator": operator, "threshold": threshold,
            **provenance, "missing_data": None,
        })
    return result


def _scenario_payload(root: Path, run_dir: Path, arguments: Mapping[str, Any]) -> dict[str, Any]:
    allowed = {
        "run_dir", "symbol", "exchange", "as_of", "mode", "horizon", "judgment",
        "next_step", "conditions", "invalidation", "review_at", "supersedes", "revision_reason",
    }
    if set(arguments) - allowed:
        raise ScenarioError("scenario contains unknown fields")
    symbol = _text(arguments.get("symbol"), "symbol", maximum=32).upper()
    if not _SYMBOL.fullmatch(symbol):
        raise ScenarioError("symbol format is invalid")
    exchange = _text(arguments.get("exchange"), "exchange", maximum=32)
    as_of_text = _text(arguments.get("as_of"), "as_of", maximum=40)
    as_of = _parse_time(as_of_text, date_end=True)
    mode = arguments.get("mode")
    if mode not in {"ultrashort", "swing", "medium"}:
        raise ScenarioError("mode must be ultrashort, swing or medium")
    horizon = _text(arguments.get("horizon"), "horizon", maximum=80)
    judgment = arguments.get("judgment")
    if judgment not in {"bullish", "bearish", "neutral", "watch", "insufficient_data"}:
        raise ScenarioError("judgment must be a supported qualitative value")
    next_step = _text(arguments.get("next_step"), "next_step", maximum=300)
    review_at = arguments.get("review_at")
    if review_at is not None:
        review_at = _text(review_at, "review_at", maximum=40)
        if _parse_time(review_at) <= as_of:
            raise ScenarioError("review_at must be later than as_of")
    evidence = _read_ledger(run_dir)
    conditions = _conditions(
        arguments.get("conditions"), symbol=symbol, as_of=as_of, evidence=evidence
    )
    invalidation = _conditions(
        arguments.get("invalidation"), symbol=symbol, as_of=as_of, evidence=evidence
    )
    supersedes = arguments.get("supersedes")
    reason = arguments.get("revision_reason")
    if supersedes is None:
        if reason not in (None, ""):
            raise ScenarioError("revision_reason is only valid when supersedes is set")
        reason = None
    else:
        if not isinstance(supersedes, str) or not _ARTIFACT_ID.fullmatch(supersedes):
            raise ScenarioError("supersedes must be an existing scenario artifact id")
        reason = _text(reason, "revision_reason", maximum=500)
    return {
        "schema_version": 1,
        "artifact_id": uuid.uuid4().hex,
        "created_at": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
        "run_id": run_dir.name,
        "symbol": symbol,
        "exchange": exchange,
        "as_of": as_of_text,
        "mode": mode,
        "horizon": horizon,
        "judgment": judgment,
        "next_step": next_step,
        "conditions": conditions,
        "invalidation": invalidation,
        "review_at": review_at,
        "supersedes": supersedes,
        "revision_reason": reason,
        "source": _producer_receipt(root),
    }


def _store_dir(root: Path, *, create: bool) -> Path:
    path = root / "research_scenarios"
    _assert_no_links(path, root)
    if create:
        path.mkdir(mode=0o700, parents=False, exist_ok=True)
    elif not path.exists():
        return path
    resolved = _private_child(path, root, strict=True)
    if not resolved.is_dir():
        raise ScenarioError("scenario index directory is invalid")
    return resolved


def _index_path(root: Path, *, create: bool) -> tuple[Path, Path]:
    directory = _store_dir(root, create=create)
    return directory, directory / "index.json"


def _read_index(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {"schema_version": 1, "items": []}
    if _is_reparse_point(path) or path.stat().st_size > 8 * 1024 * 1024:
        raise ScenarioError("scenario index is invalid or too large")
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ScenarioError("scenario index could not be read") from exc
    if not isinstance(value, dict) or value.get("schema_version") != 1 or not isinstance(value.get("items"), list):
        raise ScenarioError("scenario index has an invalid shape")
    seen: set[str] = set()
    for item in value["items"]:
        artifact_id = item.get("artifact_id") if isinstance(item, dict) else None
        if (
            not isinstance(artifact_id, str)
            or not _ARTIFACT_ID.fullmatch(artifact_id)
            or artifact_id in seen
            or not isinstance(item.get("run_id"), str)
            or not _RUN_ID.fullmatch(item["run_id"])
            or not isinstance(item.get("symbol"), str)
            or not isinstance(item.get("sha256"), str)
            or not re.fullmatch(r"[a-f0-9]{64}", item["sha256"])
        ):
            raise ScenarioError("scenario index contains an invalid entry")
        seen.add(artifact_id)
    return value


def _atomic_index_write(path: Path, value: Mapping[str, Any]) -> None:
    temporary = path.with_name(f".index-{uuid.uuid4().hex}.tmp")
    flags = os.O_CREAT | os.O_EXCL | os.O_WRONLY
    fd = os.open(temporary, flags, 0o600)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2).encode("utf-8") + b"\n")
            handle.flush()
            os.fsync(handle.fileno())
        if _is_reparse_point(path):
            raise ScenarioError("scenario index must not be a link")
        os.replace(temporary, path)
    finally:
        try:
            temporary.unlink(missing_ok=True)
        except OSError:
            pass


def _index_lock(directory: Path):
    class Lock:
        def __enter__(self):
            self.path = directory / ".index.lock"
            deadline = time.monotonic() + 5
            while True:
                try:
                    self.fd = os.open(self.path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
                    os.close(self.fd)
                    return self
                except FileExistsError:
                    if time.monotonic() >= deadline:
                        raise ScenarioError("scenario index is busy")
                    time.sleep(0.025)

        def __exit__(self, exc_type, exc, traceback):
            try:
                self.path.unlink(missing_ok=True)
            except OSError:
                pass
    return Lock()


def _scenario_path(run_dir: Path, artifact_id: str, *, create: bool) -> Path:
    artifacts = run_dir / "artifacts"
    _assert_no_links(artifacts, run_dir)
    if create:
        artifacts.mkdir(mode=0o700, exist_ok=True)
    artifacts = _private_child(artifacts, run_dir, strict=True)
    directory = artifacts / "scenarios"
    _assert_no_links(directory, run_dir)
    if create:
        directory.mkdir(mode=0o700, exist_ok=True)
    directory = _private_child(directory, run_dir, strict=True)
    return directory / f"{artifact_id}.json"


def _load_index_item(root: Path, item: Mapping[str, Any]) -> dict[str, Any]:
    artifact_id = item.get("artifact_id")
    run_id = item.get("run_id")
    if not isinstance(artifact_id, str) or not _ARTIFACT_ID.fullmatch(artifact_id):
        raise ScenarioError("scenario index contains an invalid artifact id")
    if not isinstance(run_id, str) or not _RUN_ID.fullmatch(run_id):
        raise ScenarioError("scenario index contains an invalid run id")
    _, runs = _private_roots()
    run_dir = runs / run_id
    _assert_no_links(run_dir, runs)
    resolved_run = _private_child(run_dir, runs, strict=True)
    if resolved_run.parent != runs or not resolved_run.is_dir():
        raise ScenarioError("indexed scenario run is outside the private root")
    path = _scenario_path(resolved_run, artifact_id, create=False)
    path = _private_child(path, resolved_run, strict=True)
    if path.stat().st_size > _MAX_ARTIFACT_BYTES:
        raise ScenarioError("scenario artifact is too large")
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != item.get("sha256"):
        raise ScenarioError("scenario artifact integrity check failed")
    try:
        artifact = json.loads(raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ScenarioError("scenario artifact could not be decoded") from exc
    if (
        not isinstance(artifact, dict)
        or artifact.get("artifact_id") != artifact_id
        or artifact.get("run_id") != run_id
        or artifact.get("symbol") != item.get("symbol")
    ):
        raise ScenarioError("scenario index does not match its artifact")
    return artifact


def _write_exclusive(path: Path, data: bytes) -> None:
    fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
    with os.fdopen(fd, "wb") as handle:
        handle.write(data)
        handle.flush()
        os.fsync(handle.fileno())


def record_scenario(run_dir: str | Path, arguments: Mapping[str, Any]) -> dict[str, Any]:
    """Validate, append, and index one immutable scenario artifact."""
    root, _runs, resolved_run = _private_run_dir(run_dir)
    payload = _scenario_payload(root, resolved_run, arguments)
    directory, index_path = _index_path(root, create=True)
    if _is_reparse_point(index_path):
        raise ScenarioError("scenario index must not be a link")
    artifact_path = _scenario_path(resolved_run, payload["artifact_id"], create=True)
    _private_child(artifact_path.parent, resolved_run, strict=True)
    data = json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2).encode("utf-8") + b"\n"
    if len(data) > _MAX_ARTIFACT_BYTES:
        raise ScenarioError("scenario artifact is too large")
    with _index_lock(directory):
        index = _read_index(index_path)
        items = index["items"]
        if payload["supersedes"] is not None:
            prior = next((row for row in items if isinstance(row, dict) and row.get("artifact_id") == payload["supersedes"]), None)
            if prior is None:
                raise ScenarioError("supersedes must name an indexed scenario")
            previous = _load_index_item(root, prior)
            if previous.get("symbol") != payload["symbol"]:
                raise ScenarioError("superseded scenario must have the same symbol")
        created = False
        try:
            _write_exclusive(artifact_path, data)
            created = True
            item = {
                "artifact_id": payload["artifact_id"],
                "run_id": payload["run_id"],
                "symbol": payload["symbol"],
                "created_at": payload["created_at"],
                "sha256": hashlib.sha256(data).hexdigest(),
                "supersedes": payload["supersedes"],
                "revision_reason": payload["revision_reason"],
            }
            _atomic_index_write(index_path, {"schema_version": 1, "items": [*items, item]})
        except Exception:
            if created:
                artifact_path.unlink(missing_ok=True)
            raise
    return payload


def list_scenarios(*, limit: int = 200) -> list[dict[str, Any]]:
    """Return indexed scenarios after validating each private artifact hash."""
    if not isinstance(limit, int) or isinstance(limit, bool) or not 1 <= limit <= 500:
        raise ScenarioError("scenario list limit is out of range")
    root = _private_runtime_root()
    _directory, index_path = _index_path(root, create=False)
    index = _read_index(index_path)
    items = index["items"]
    if len(items) > 100_000:
        raise ScenarioError("scenario index contains too many entries")
    artifacts = [_load_index_item(root, item) for item in items if isinstance(item, dict)]
    artifacts.sort(key=lambda item: (str(item.get("created_at", "")), item["artifact_id"]), reverse=True)
    return artifacts[:limit]


def get_scenario(artifact_id: str) -> dict[str, Any] | None:
    """Return one indexed scenario by opaque id, never by a supplied path."""
    if not isinstance(artifact_id, str) or not _ARTIFACT_ID.fullmatch(artifact_id):
        return None
    root = _private_runtime_root()
    _directory, index_path = _index_path(root, create=False)
    index = _read_index(index_path)
    item = next(
        (row for row in index["items"] if isinstance(row, dict) and row.get("artifact_id") == artifact_id),
        None,
    )
    return _load_index_item(root, item) if item is not None else None


def observe_conditions(
    artifact: Mapping[str, Any],
    observed_facts: Sequence[Mapping[str, Any]],
    observed_at: str,
    max_age: timedelta | int | float,
) -> dict[str, Any]:
    """Compare later source-backed observations with recorded conditions only.

    The result describes rule matches, invalidation and review expiry. It does
    not assess forecast accuracy, investment performance or profitability.
    """
    if not isinstance(artifact, Mapping) or not isinstance(observed_facts, Sequence):
        raise ScenarioError("artifact and observed facts are required")
    as_of = _parse_time(artifact.get("as_of"), date_end=True)
    at = _parse_time(observed_at)
    if isinstance(max_age, timedelta):
        age_limit = max_age
    elif _is_number(max_age):
        age_limit = timedelta(seconds=float(max_age))
    else:
        raise ScenarioError("max_age must be a duration or seconds")
    if age_limit < timedelta(0):
        raise ScenarioError("max_age must not be negative")
    symbol = str(artifact.get("symbol") or "").strip().upper()
    if not _SYMBOL.fullmatch(symbol):
        raise ScenarioError("artifact symbol is invalid")
    review_at = artifact.get("review_at")
    expired = review_at is not None and at >= _parse_time(review_at)

    def evaluate(rows: Any, group: str) -> list[dict[str, Any]]:
        if not isinstance(rows, list):
            return []
        result: list[dict[str, Any]] = []
        for condition_index, condition in enumerate(rows):
            if not isinstance(condition, Mapping):
                continue
            field = condition.get("field")
            operator = condition.get("operator")
            threshold = condition.get("threshold")
            evidence_ref = condition.get("evidence_ref")
            row: dict[str, Any] = {
                "group": group,
                "condition_index": condition_index,
                "field": field,
                "operator": operator,
                "evidence_ref": evidence_ref,
                "status": "missing_data",
            }
            if expired:
                row["status"] = "expired"
                result.append(row)
                continue
            if (
                not isinstance(field, str)
                or not _FIELD.fullmatch(field)
                or operator not in _OPERATORS
                or not _is_number(threshold)
                or not isinstance(evidence_ref, str)
                or not evidence_ref.startswith("sha256:")
            ):
                result.append(row)
                continue
            candidates: list[tuple[datetime, Mapping[str, Any]]] = []
            for fact in observed_facts:
                if not isinstance(fact, Mapping):
                    continue
                source = fact.get("source")
                if (
                    fact.get("status") != "observed"
                    or not isinstance(source, str)
                    or source.strip().casefold() in _SOURCELESS
                    or str(fact.get("symbol") or "").strip().upper() != symbol
                    or str(fact.get("field") or "").strip().casefold() != field
                    or not _is_number(fact.get("value"))
                ):
                    continue
                try:
                    timestamp = _parse_time(fact.get("timestamp"))
                except ScenarioError:
                    continue
                if as_of < timestamp <= at:
                    candidates.append((timestamp, fact))
            if not candidates:
                row["status"] = "no_newer_observation"
                result.append(row)
                continue
            timestamp, fact = max(candidates, key=lambda item: item[0])
            row.update({"source": fact["source"], "observed_at": fact["timestamp"]})
            if at - timestamp > age_limit:
                row["status"] = "stale"
                result.append(row)
                continue
            observed_value = fact["value"]
            matched = {
                "gt": observed_value > threshold,
                "gte": observed_value >= threshold,
                "lt": observed_value < threshold,
                "lte": observed_value <= threshold,
                "equal": observed_value == threshold,
            }[operator]
            row["status"] = "met" if matched else "not_met"
            row["value"] = observed_value
            result.append(row)
        return result

    conditions = evaluate(artifact.get("conditions"), "conditions")
    invalidations = evaluate(artifact.get("invalidation"), "invalidation")
    return {
        "artifact_id": artifact.get("artifact_id"),
        "symbol": symbol,
        "observed_at": _timestamp(at),
        "triggered": bool(conditions) and all(row["status"] == "met" for row in conditions),
        "invalidated": any(row["status"] == "met" for row in invalidations),
        "expired": expired,
        "conditions": conditions,
        "invalidation": invalidations,
        "meaning": "condition matches only; not forecast accuracy or investment performance",
    }

