        },
        "missing_data": {"type": ["string", "null"]},
    },
}


class RecordResearchScenarioTool(BaseTool):
    name = "record_research_scenario"
    description = (
        "Append a qualitative research scenario to the active run. Numeric condition thresholds "
        "must exactly match source-backed observed market facts in that run's grounding ledger; "
        "leave a threshold null and explain missing_data when no such fact exists. Do not include "
        "forecast probabilities or target prices. A superseding revision must cite an existing "
        "artifact id and explain the revision."
    )
    is_readonly = False
    parameters = {
        "type": "object",
        "additionalProperties": False,
        "required": [
            "symbol", "exchange", "as_of", "mode", "horizon", "judgment", "next_step",
            "conditions", "invalidation", "review_at", "supersedes", "revision_reason",
        ],
        "properties": {
            "symbol": {"type": "string", "minLength": 1, "maxLength": 32},
            "exchange": {"type": "string", "minLength": 1, "maxLength": 32},
            "as_of": {"type": "string", "description": "ISO date or datetime; facts may not be later."},
            "mode": {"type": "string", "enum": ["ultrashort", "swing", "medium"]},
            "horizon": {
                "type": "string", "minLength": 1, "maxLength": 80,
                "description": "Time horizon only; do not include probabilities or target prices.",
            },
            "judgment": {"type": "string", "enum": ["bullish", "bearish", "neutral", "watch", "insufficient_data"]},
            "next_step": {
                "type": "string", "minLength": 1, "maxLength": 300,
                "description": "Qualitative follow-up action; no probability or target price fields are supported.",
            },
            "conditions": {"type": "array", "maxItems": 30, "items": _CONDITION},
            "invalidation": {"type": "array", "maxItems": 30, "items": _CONDITION},
            "review_at": {"type": ["string", "null"]},
            "supersedes": {"type": ["string", "null"], "pattern": "^[a-f0-9]{32}$"},
            "revision_reason": {"type": ["string", "null"], "maxLength": 500},
        },
    }

    @classmethod
    def check_available(cls) -> bool:
        return os.environ.get("VIBE_TRADING_HOSTED") == "1"

    def execute(self, **kwargs: Any) -> str:
        run_dir = kwargs.pop("run_dir", None)
        try:
            artifact = record_scenario(run_dir, kwargs)
            return json.dumps({"status": "ok", **artifact}, ensure_ascii=False)
        except ScenarioError as exc:
            return json.dumps({"status": "error", "error": str(exc)}, ensure_ascii=False)
        except (OSError, ValueError):
            return json.dumps({"status": "error", "error": "scenario could not be safely recorded"}, ensure_ascii=False)

