"""Read-only hosted API for persisted native research scenarios."""

import os

from fastapi import Depends, FastAPI, HTTPException

from src.api.security import require_auth
from src.research_scenarios import ScenarioError, get_scenario, list_scenarios


def register_mona_scenarios(app: FastAPI) -> None:
    if os.environ.get("VIBE_TRADING_HOSTED") != "1":
        return

    @app.get("/mona/scenarios", dependencies=[Depends(require_auth)])
    async def get_scenarios():
        try:
            return {"scenarios": list_scenarios(limit=200)}
        except (ScenarioError, OSError, ValueError) as exc:
            raise HTTPException(status_code=503, detail="Scenarios are unavailable") from exc

    @app.get("/mona/scenarios/{artifact_id}", dependencies=[Depends(require_auth)])
    async def get_scenario_detail(artifact_id: str):
        try:
            scenario = get_scenario(artifact_id)
        except (ScenarioError, OSError, ValueError) as exc:
            raise HTTPException(status_code=503, detail="Scenario is unavailable") from exc
        if scenario is None:
            raise HTTPException(status_code=404, detail="Scenario not found")
        return scenario
